package main

import "fmt"

var n, m, k int64

// Minimum jobs on `cnt` processors next to one holding x: x-1, x-2, ..., then 1s.
func side(cnt, x int64) int64 {
	full := min(cnt, x-1)
	return (x-1+x-full)*full/2 + max(0, cnt-full)
}

func need(x int64) int64 { return x + side(k-1, x) + side(n-k, x) }

func main() {
	fmt.Scan(&n, &m, &k)
	lo, hi, ans := int64(1), m, int64(1)
	for lo <= hi {
		mid := (lo + hi) / 2
		if need(mid) <= m {
			ans, lo = mid, mid+1
		} else {
			hi = mid - 1
		}
	}
	fmt.Println(ans)
}
